:root {
  --card-bg: #fff8f0;
  --card-border: #f4c57a;
  --header-bg: #fb923c;
  --header-text: #ffffff;
  --title-size: 20px;
  --sub-color: #ffe4c4;
  --badge-bg: #fef08a;
  --badge-text: #92400e;
  --chip-strawberry-bg: #fecdd3;
  --chip-strawberry-text: #9f1239;
  --chip-mint-bg: #d1fae5;
  --chip-mint-text: #065f46;
  --chip-vanilla-bg: #fef9c3;
  --chip-vanilla-text: #713f12;
  --footer-bg: #fff3e4;
  --footer-label: #a0522d;
  --footer-count: #c2410c;
}

.loyalty-card {
  background-color: var(--card-bg);
  border: 2px solid var(--card-border);
  border-radius: 16px;
  width: 320px;
  overflow: hidden;
}

.card-header {
  background-color: var(--header-bg);
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 14px 16px;
}

.card-icon {
  font-size: 28px;
  line-height: 1;
}

.card-titles {
  flex: 1;
}

.card-title {
  margin: 0;
  font-size: var(--title-size);
  font-weight: 800;
  color: var(--header-text);
  line-height: 1.1;
}

.card-sub {
  margin: 0;
  font-size: 12px;
  color: var(--sub-color);
  font-weight: 500;
}

.card-badge {
  background-color: var(--badge-bg);
  color: var(--badge-text);
  font-size: 12px;
  font-weight: 700;
  padding: 4px 10px;
  border-radius: 999px;
}

.flavor-row {
  display: flex;
  gap: 8px;
  padding: 16px;
  justify-content: center;
}

.flavor-chip {
  font-size: 13px;
  font-weight: 600;
  padding: 6px 14px;
  border-radius: 999px;
}

.chip-strawberry {
  background-color: var(--chip-strawberry-bg);
  color: var(--chip-strawberry-text);
}

.chip-mint {
  background-color: var(--chip-mint-bg);
  color: var(--chip-mint-text);
}

.chip-vanilla {
  background-color: var(--chip-vanilla-bg);
  color: var(--chip-vanilla-text);
}

.card-footer {
  background-color: var(--footer-bg);
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 10px 16px;
  border-top: 1px solid var(--card-border);
}

.footer-label {
  margin: 0;
  font-size: 13px;
  font-weight: 600;
  color: var(--footer-label);
}

.footer-count {
  margin: 0;
  font-size: 18px;
  font-weight: 800;
  color: var(--footer-count);
}
